package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.NoSuchElementException;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonGradeService;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRetiredException;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on a sheet make. */
@Service
public class ClaimService {

    /** Written for a due that has no rate to work from. */
    private static final String NO_RATE = "n/a";

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateService rates;
    private final PersonGradeService grades;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingService settings;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates,
            PersonGradeService grades, SheetService sheets, PeriodRepository periods, SettingService settings, Audit audit) {
        this.periods = periods;
        this.settings = settings;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.grades = grades;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /** Add a claim for a person; a missing date takes the sheet's today. A negative amount is a
     *  correction and must name a SETTLED claim of the person it corrects. */
    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            Long corrects) {
        Person person = person(sheetId, personId);
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, noteOf(note), corrects));
        record("CLAIM_ADDED", sheetId, user, person, added);
        return added;
    }

    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
    @Transactional
    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
            String note, Long corrects) {
        Person person = person(sheetId, personId);
        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(claim.getStatus());
        }
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDate());
        refuseClosed(sheetId, on);
        refuseRetired(person, on);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        claim.setAmount(scaled(amount));
        claim.setCorrects(corrects);
        claim.setDate(on);
        claim.setNote(noteOf(note));
        Claim saved = claims.saveAndFlush(claim);
        record("CLAIM_EDITED", sheetId, user, person, saved);
        return saved;
    }

    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
     *  who opened a claim settling it, and a clerk settling a claim whose due is above the clerk
     *  limit. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
        Person person = person(sheetId, personId);
        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
        // read below is its latest state.
        Long number = to == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
        refuseClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canMoveTo(to)) {
            throw new StatusChangeRefusedException(claim.getStatus(), to);
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new OwnClaimSettleRefusedException(user);
        }
        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
        // gathered by then.
        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
        if (to == ClaimStatus.SETTLED) {
            refuseOverClerkLimit(sheetId, user, due);
        }
        claim.setStatus(to);
        if (to == ClaimStatus.OPEN) {
            claim.setNumber(number);
            claim.setOpenedBy(user);
        } else if (to == ClaimStatus.SETTLED) {
            claim.setSettledDue(due);
        }
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (to) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
        };
        String line = line(event, sheetId, user, person, saved, saved.getNumber());
        if (to == ClaimStatus.SETTLED) {
            line += " due=" + (saved.getSettledDue() != null ? saved.getSettledDue().toPlainString() : NO_RATE);
        }
        audit.recordOnCommit(line);
        return saved;
    }

    /** The figure a claim shows: the due fixed when it was settled, else the figure its person's
     *  last statement bound it to, else its due at the person's grade rate; null when it has none. */
    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : liveFigureOf(sheetId, person, claim);
    }

    /** The due a claim shows: its figure plus its late charge; null when it has no figure. */
    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
        BigDecimal figure = figureOf(sheetId, person, claim);
        return figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure));
    }

    /** The late charge on a claim with a figure: none unless it is OPEN and overdue (its date plus the
     *  terms is before the sheet's today) or a correction, else the late percent of the figure for every full 30 days
     *  it is overdue, rounded to two decimals as the claim's date decides (see roundingOf). Never bound by a statement: it follows the
     *  sheet's today. */
    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isCorrection()) {
            return none;
        }
        LocalDate dueBy = claim.getDate().plusDays(settings.terms(sheetId));
        long days = ChronoUnit.DAYS.between(dueBy, sheets.today(sheetId));
        if (days < 30) {
            return none;
        }
        return figure.multiply(settings.latePct(sheetId)).multiply(BigDecimal.valueOf(days / 30))
                .movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
    }

    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
     *  on the claim's date: amount times rate
     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf), and at least the sheet's floor unless it
     *  is a correction; null when no rate applies. */
    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
        BigDecimal amount = claim.getAmount();
        RoundingMode rounding = roundingOf(sheetId, claim);
        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
                .map(Rate::getRate)
                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
                .map(due -> claim.isCorrection() ? due : due.max(settings.floor(sheetId)))
                .orElse(null);
    }

    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
     *  it corrects. */
    public LocalDate roundsBy(String sheetId, Claim claim) {
        if (!claim.isCorrection() || claim.getCorrects() == null) {
            return claim.getDate();
        }
        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
                .map(Claim::getDate).orElse(claim.getDate());
    }

    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
    private RoundingMode roundingOf(String sheetId, Claim claim) {
        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
    }

    /** A clerk cannot settle a claim whose due is above the sheet's clerk limit; a due of n/a is
     *  within any limit, and a steward settles anything. */
    private void refuseOverClerkLimit(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = settings.clerkLimit(sheetId);
        if (limit == null || due == null || due.compareTo(limit) <= 0) {
            return;
        }
        if (settings.roleOf(sheetId, user) == Role.CLERK) {
            throw new ClerkLimitRefusedException(user, due, limit);
        }
    }

    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
     *  any other amount names none. */
    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, Long corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) {
                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
            }
            return;
        }
        if (corrects == null) {
            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
        }
        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
        if (!settled) {
            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
        }
    }

    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
    private void refuseClosed(String sheetId, LocalDate date) {
        if (periods.closedOn(sheetId, date)) {
            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
        }
    }

    /** A claim dated after its person's retirement date cannot be added or moved there. */
    private static void refuseRetired(Person person, LocalDate date) {
        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
        }
    }

    private Person person(String sheetId, Long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
    }

    private void record(String event, String sheetId, String user, Person person, Claim claim) {
        record(event, sheetId, user, person, claim, claim.getNumber());
    }

    /** One audit line about a claim; a claim with a number carries it at the end. */
    private void record(String event, String sheetId, String user, Person person, Claim claim, Long number) {
        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
    }

    private static String line(String event, String sheetId, String user, Person person, Claim claim, Long number) {
        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
                + (number != null ? " number=" + number : "");
    }

    private static BigDecimal scaled(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.UNNECESSARY);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (DRAFT
 *  when added). A claim with a negative amount is a correction, naming the number of the SETTLED
 *  claim of the same person it corrects. */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(name = "note", nullable = false)
    private String note;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status = ClaimStatus.DRAFT;

    /** The claim's number on its sheet, given when it is opened and kept when it is
     *  voided (never reused); null for a claim never opened. */
    @Column(name = "claim_number")
    private Long number;

    /** The due fixed when the claim was settled; null until then, or when its grade had no rate. */
    @Column(name = "settled_due", precision = 12, scale = 2)
    private BigDecimal settledDue;

    /** The user who opened the claim; null for a claim never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** Whether the person's last statement bound the claim to the figure it had then. */
    @Column(name = "stated", nullable = false)
    private boolean stated;

    /** The figure the claim was bound to by a statement; null when unbound or it had no figure. */
    @Column(name = "stated_due", precision = 12, scale = 2)
    private BigDecimal statedDue;

    /** The number of the claim this correction corrects; null for a claim that is not a correction. */
    @Column(name = "corrects_number")
    private Long corrects;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, Long corrects) {
        this.sheetId = sheetId;
        this.corrects = corrects;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public Long getCorrects() {
        return corrects;
    }

    public void setCorrects(Long corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: its amount is negative. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    public Long getNumber() {
        return number;
    }

    public void setNumber(Long number) {
        this.number = number;
    }

    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Bind the claim to a figure (may be null: it had none). */
    public void bind(BigDecimal due) {
        this.stated = true;
        this.statedDue = due;
    }

    /** Leave the claim unbound, its figure live again. */
    public void unbind() {
        this.stated = false;
        this.statedDue = null;
    }

    /** Whether the claim counts toward what is claimed and due: only OPEN and SETTLED ones do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /** Whether the claim counts in live totals, its person held or not: while held, only SETTLED ones do. */
    public boolean countsLive(boolean personHeld) {
        return personHeld ? status == ClaimStatus.SETTLED : counts();
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its terms and
 *  its late percent and its policy date. */
@Service
public class SettingService {

    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final SheetRoleRepository roles;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
            Audit audit) {
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.roles = roles;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless assigned another. */
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The sheet's clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return sheets.load(sheetId).getClerkLimit();
    }

    /** The sheet's floor: the least a claim's live due can be. */
    public BigDecimal floor(String sheetId) {
        return sheets.load(sheetId).getFloor();
    }

    /** The sheet's terms in days: a claim is due by its date plus them. */
    public int terms(String sheetId) {
        return sheets.load(sheetId).getTerms();
    }

    /** The sheet's late percent: an overdue claim's due gains it of its figure for every full 30 days
     *  it is overdue. */
    public BigDecimal latePct(String sheetId) {
        return sheets.load(sheetId).getLatePct();
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today applies). */
    public LocalDate policyDateSet(String sheetId) {
        return sheets.load(sheetId).getPolicyDate();
    }

    /** The sheet's policy date in force: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
     *  after it. */
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return date.isBefore(policyDate(sheetId)) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Assign a user name a role on the sheet. */
    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        sheets.lock(sheetId);
        SheetRole saved = roles.findBySheetIdAndUser(sheetId, user)
                .map(existing -> {
                    existing.setRole(role);
                    return existing;
                })
                .orElseGet(() -> new SheetRole(sheetId, user, role));
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role.label());
        return saved;
    }

    /** Change the sheet's clerk limit; null removes it. */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String by, BigDecimal limit) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null;
        sheet.setClerkLimit(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=clerk-limit value="
                + (scaled != null ? scaled.toPlainString() : ""));
        return saved;
    }

    /** Change the sheet's floor. */
    @Transactional
    public Sheet setFloor(String sheetId, String by, BigDecimal floor) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = floor.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setFloor(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=floor value="
                + scaled.toPlainString());
        return saved;
    }

    /** Change the sheet's terms. */
    @Transactional
    public Sheet setTerms(String sheetId, String by, int terms) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setTerms(terms);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=terms value=" + terms);
        return saved;
    }

    /** Change the sheet's late percent. */
    @Transactional
    public Sheet setLatePct(String sheetId, String by, BigDecimal latePct) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        BigDecimal scaled = latePct.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setLatePct(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=late-pct value="
                + scaled.toPlainString());
        return saved;
    }

    /** Change the sheet's policy date; null leaves it blank (the sheet's today). */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        return saved;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, identified by the id a user types. Everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    /** The sheet's today: every date-dependent decision and default date on the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number given on the sheet; the next claim opened takes the one after. */
